50	
51	    float q_reg[ROWS_PER_WARP][D_PER_LANE];
52	    float acc[ROWS_PER_WARP][D_PER_LANE];
53	    float row_max[ROWS_PER_WARP];
54	    float row_sum[ROWS_PER_WARP];
55	
56	#pragma unroll
57	    for (int r = 0; r < ROWS_PER_WARP; ++r) {
58	        row_max[r] = -INFINITY;
59	        row_sum[r] = 0.f;
60	        const int grow = m_tile * BLOCK_M + warp * ROWS_PER_WARP + r;
61	#pragma unroll
62	        for (int j = 0; j < D_PER_LANE; ++j) {
63	            acc[r][j] = 0.f;
64	            q_reg[r][j] = (grow < seq_len)
65	                ? __bfloat162float(q[base + (long long)grow * HEAD_DIM + d0 + j])
66	                : 0.f;
67	        }
68	    }
69	
70	    const int row_hi = min(m_tile * BLOCK_M + BLOCK_M - 1, seq_len - 1);
71	    int n_tiles = (seq_len + BLOCK_N - 1) / BLOCK_N;
72	    if (causal) n_tiles = min(n_tiles, row_hi / BLOCK_N + 1);
73	
74	    for (int nt = 0; nt < n_tiles; ++nt) {
75	        // Cooperative K/V tile load into shared memory.
76	        for (int idx = threadIdx.x; idx < BLOCK_N * HEAD_DIM; idx += NUM_THREADS) {
77	            const int row = idx / HEAD_DIM;
78	            const int col = idx % HEAD_DIM;
79	            const int grow_kv = nt * BLOCK_N + row;
80	            if (grow_kv < seq_len) {
81	                sK[row][col] = k[base + (long long)grow_kv * HEAD_DIM + col];
82	                sV[row][col] = v[base + (long long)grow_kv * HEAD_DIM + col];
83	            } else {
84	                sK[row][col] = __float2bfloat16(0.f);
85	                sV[row][col] = __float2bfloat16(0.f);
86	            }
87	        }
88	        __syncthreads();
89	
90	        for (int r = 0; r < ROWS_PER_WARP; ++r) {
91	            const int grow = m_tile * BLOCK_M + warp * ROWS_PER_WARP + r;
92	            if (grow >= seq_len) continue;  // uniform across the warp
93	            for (int c = 0; c < BLOCK_N; ++c) {
